import { useRef, useState } from 'react';
import { AlertTriangle, Loader2, Pause, Play, RefreshCw, Sparkles } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { useDailyBrief } from '@/hooks/useDashboard';
import { useBriefAudio } from '@/hooks/useBriefAudio';
import { errorMessage } from '@/lib/queryClient';
import { formatDate } from '@/utils/format';

/** "Today's Brief": Nepali spoken summary generated by the backend. Playback only. */
export function DailyBriefCard({ shopId }: { shopId: string }) {
  const { data: brief, isLoading, isError, error, refetch, isFetching } = useDailyBrief(shopId);
  const audio = useBriefAudio(shopId);
  const audioEl = useRef<HTMLAudioElement>(null);
  const [playing, setPlaying] = useState(false);

  const toggle = async () => {
    const el = audioEl.current;
    if (!el) return;
    if (playing) {
      el.pause();
      return;
    }
    const src = await audio.load();
    if (!src) return;
    if (el.src !== src) el.src = src;
    await el.play().catch(() => setPlaying(false));
  };

  return (
    <section className="bg-surface rounded-2xl border border-border shadow-sm overflow-hidden">
      <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100">
        <div className="flex items-center gap-2">
          <Sparkles className="size-4 text-brand" />
          <h2 className="font-semibold text-[15px] text-foreground">Today's Brief</h2>
        </div>
        {brief && <span className="text-xs text-muted-foreground">{formatDate(brief.brief_date)}</span>}
      </div>

      <div className="p-6">
        {isLoading ? (
          <div className="flex gap-4" aria-busy="true" aria-label="Loading brief">
            <Skeleton className="size-12 rounded-full shrink-0" />
            <div className="flex-1 space-y-2">
              <Skeleton className="h-4 w-full" />
              <Skeleton className="h-4 w-5/6" />
              <Skeleton className="h-4 w-2/3" />
            </div>
          </div>
        ) : isError || !brief ? (
          <div className="flex flex-col sm:flex-row sm:items-center gap-3 justify-between">
            <div className="flex items-start gap-2 text-sm">
              <AlertTriangle className="size-4 text-warning mt-0.5 shrink-0" />
              <div>
                <p className="font-medium text-foreground">Today's brief isn't available yet</p>
                <p className="text-muted-foreground">{errorMessage(error, 'The brief could not be generated.')}</p>
              </div>
            </div>
            <Button variant="outline" size="sm" onClick={() => refetch()} disabled={isFetching}>
              <RefreshCw className={isFetching ? 'animate-spin' : ''} /> Try again
            </Button>
          </div>
        ) : (
          <div className="flex gap-4">
            <div className="shrink-0">
              <Button
                size="icon-lg"
                className="rounded-full size-12"
                onClick={toggle}
                disabled={audio.loading}
                aria-label={playing ? 'Pause brief' : 'Play brief'}
              >
                {audio.loading ? <Loader2 className="animate-spin" /> : playing ? <Pause /> : <Play className="ml-0.5" />}
              </Button>
              <audio
                ref={audioEl}
                onPlay={() => setPlaying(true)}
                onPause={() => setPlaying(false)}
                onEnded={() => setPlaying(false)}
                hidden
              />
            </div>
            <div className="min-w-0 flex-1 space-y-3">
              <p lang="ne" className="text-[15px] leading-relaxed text-slate-700 whitespace-pre-line">
                {brief.transcript}
              </p>
              {brief.ai_insight && brief.ai_insight !== brief.transcript && (
                <div className="flex gap-2 rounded-xl bg-brand-soft border border-red-100 px-4 py-3">
                  <Sparkles className="size-4 text-brand mt-0.5 shrink-0" />
                  <p lang="ne" className="text-sm font-medium text-red-900">
                    {brief.ai_insight}
                  </p>
                </div>
              )}
              {audio.error && <p className="text-xs text-danger">{audio.error}</p>}
            </div>
          </div>
        )}
      </div>
    </section>
  );
}
